.dnd-lift {
  box-shadow: 0 10px 28px -10px hsl(var(--foreground) / 0.2), 0 4px 10px -4px hsl(var(--foreground) / 0.1);
  outline: 1.5px solid hsl(var(--ring) / 0.9);
  outline-offset: 0;
  transform: rotate(0.6deg) scale(1.015);
  z-index: 50;
}
.dnd-over {
  outline: 1.5px dashed hsl(var(--ring) / 0.45);
  outline-offset: 2px;
  background: hsl(var(--accent) / 0.5);
}

/* Smooth sortable transitions */
[data-sortable] { will-change: transform; }
